<template><el-card><h1>文档管理</h1><el-upload :http-request="upload" :show-file-list="false" accept=".docx"><el-button type="primary">上传 Word 并入库</el-button></el-upload><el-table :data="docs" style="margin-top:16px"><el-table-column prop="title" label="文档名称"/><el-table-column prop="word_count" label="单词数量"/><el-table-column prop="status" label="状态"/><el-table-column prop="created_at" label="创建时间"/><el-table-column label="操作"><template #default="scope"><el-button link @click="$router.push(`/file/preview/${scope.row.id}`)">预览</el-button><el-button link>下载原版</el-button><el-button link>下载默写版</el-button></template></el-table-column></el-table></el-card></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{listDocuments,uploadDocument}from'@/api/client';const docs=ref([]);async function load(){const{data}=await listDocuments();docs.value=data.data.items}async function upload({file}){const form=new FormData();form.append('title',file.name);form.append('file',file);await uploadDocument(form);ElMessage.success('上传解析完成，数据已入库');load()}onMounted(load)</script>
